/*	Turn an n8n failure into something a human can act on, and work out whether it can
	be attached to a record in Administrate	*/

const cfg = $('Config').first().json;
const err = $('Workflow Failed').first().json || {};

const wf = err.workflow || {};
const ex = err.execution || {};
const lastNode = String(ex.lastNodeExecuted || 'unknown');
const message = String((ex.error || {}).message || (ex.error || {}).description || 'No message supplied');

/*	Transient failures resolve on a retry. Everything else needs a person	*/
const transientMarkers = String(cfg.TRANSIENT_MARKERS).split(',');
let transient = false;

for (const marker of transientMarkers) {
	if (marker.trim() !== '' && message.indexOf(marker.trim()) !== -1) { transient = true; }
}

/*	The error trigger payload never carries the failing workflow's data, so the event id
	is recovered from the fetched execution instead. Look through the nodes most likely
	to hold it, in order, and take the first plausible value	*/
const fetched = $input.first().json || {};
const runData = ((((fetched.data || {}).resultData) || {}).runData) || {};

const nodeNames = String(cfg.EVENT_ID_NODES).split(',').map(n => n.trim()).filter(n => n !== '');
const fieldNames = String(cfg.EVENT_ID_FIELDS).split(',').map(n => n.trim()).filter(n => n !== '');

let eventId = '';

for (const nodeName of nodeNames) {
	if (eventId !== '') { break; }
	const runs = runData[nodeName];
	if (!Array.isArray(runs) || runs.length === 0) { continue; }
	const items = ((((runs[0].data || {}).main) || [])[0]) || [];
	for (const item of items) {
		if (eventId !== '') { break; }
		for (const field of fieldNames) {
			const candidate = String(((item || {}).json || {})[field] || '');
			/*	Administrate ids are base64 and decode to Course:N - a malformed one is
				no use as a log target, so require it to look like an id	*/
			if (candidate !== '' && /^[A-Za-z0-9+/=]+$/.test(candidate)) { eventId = candidate; break; }
		}
	}
}

/*	This entry lands on the event, where a coordinator reads it, not in a developer's
	console. It opens with what it means for them and whether anything is expected of
	them, then carries the technical detail afterwards for whoever has to fix it	*/
const plain = transient
	? 'A temporary problem interrupted the automation for this event. These usually clear on their own, so no action is needed unless it keeps happening.'
	: 'The automation could not finish something for this event and needs somebody to look at it. Nothing on the event has been changed.';

const summary = plain + ' Detail: ' + String(wf.name || 'unknown workflow') + ' failed at ' + lastNode + '. ' + message;

return [{ json: {
	hasEvent: eventId !== '',
	eventId: eventId,
	transient: transient,
	summary: summary,
	payload: JSON.stringify({ workflowId: wf.id || null, workflowName: wf.name || null, executionId: ex.id || null, lastNode: lastNode, transient: transient, message: message })
} }];
